function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const now = new Date();
const end = new Date(now.getTime() - 24 * 3600 * 1000);
const start = new Date(now.getTime() - 7 * 24 * 3600 * 1000);
function fmt(d) {
  return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'Europe/Amsterdam' });
}
function fmtShort(d) {
  return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', timeZone: 'Europe/Amsterdam' });
}
const rangeLine = fmt(start) + ' to ' + fmt(end);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const concepts = Array.isArray(j.concepts) ? j.concepts : [];
  if (concepts.length === 0) continue;

  const rows = concepts.map(function (c) {
    const sourceLabel = c.source && c.source.length > 0 ? '<div style="font-size:12px;color:#9ca3af;margin-top:6px;">' + esc(c.source) + '</div>' : '';
    const whyLine = c.why && c.why.length > 0 ? '<div style="font-size:14px;color:#555555;margin-top:6px;line-height:1.55;">' + esc(c.why) + '</div>' : '';
    return '<tr><td style="padding:18px 0;border-bottom:1px solid #eeeeee;">' +
      '<a href="' + esc(c.url) + '" style="font-size:16px;font-weight:700;color:#1264a3;text-decoration:none;line-height:1.4;">' + esc(c.headline) + '</a>' +
      whyLine + sourceLabel + '</td></tr>';
  }).join('');

  const count = concepts.length;
  const findWord = count === 1 ? 'find' : 'finds';
  const greeting = j.first_name && j.first_name.length > 0 ? 'Hope you had a good weekend, ' + esc(j.first_name) + '.' : 'Hope you had a good weekend.';

  const html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f4f4;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f4;"><tr><td align="center" style="padding:32px 16px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif;">' +
    '<tr><td align="center" style="padding-bottom:24px;">' +
    '<div style="font-size:20px;font-weight:800;color:#111111;letter-spacing:-0.02em;">wingsuite <span style="font-weight:400;">radar</span></div>' +
    '</td></tr>' +
    '<tr><td style="background:#ffffff;border-radius:12px;border:1px solid #e8e8e8;padding:40px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' +
    '<tr><td align="center" style="padding-bottom:24px;"><div style="font-size:14px;font-weight:700;color:#111111;">' + rangeLine + '</div></td></tr>' +
    '<tr><td style="padding-bottom:8px;"><div style="font-size:15px;color:#333333;line-height:1.6;">' + greeting + ' Here is what Radar picked up from your sources last week: ' + count + ' ' + findWord + ', each checked against your priorities.</div></td></tr>' +
    '<tr><td><table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + rows + '</table></td></tr>' +
    '<tr><td style="padding-top:24px;"><a href="https://console.wingsuite.io/radar" style="font-size:14px;font-weight:600;color:#1264a3;text-decoration:none;">Open Radar to draft from a find</a></td></tr>' +
    '</table>' +
    '</td></tr>' +
    '<tr><td align="center" style="padding:24px 16px 0;"><div style="font-size:12px;color:#9ca3af;line-height:1.6;">You get this once a week, on Monday morning, and only when Radar found something.</div></td></tr>' +
    '</table></td></tr></table></body></html>';

  out.push({ json: {
    email: j.email,
    subject: '[Radar] Your finds for the week of ' + fmtShort(start),
    html: html
  } });
}

return out;

